SELECT id FROM ai_quota_reservations
WHERE user_id = #{userId} AND status = 'RESERVED' AND expires_at <= #{now}
ORDER BY expires_at ASC, id ASC

SELECT id FROM ai_quota_reservations
WHERE status = 'RESERVED' AND expires_at <= #{now}
ORDER BY expires_at ASC, id ASC
LIMIT #{maximumCount}

