UPDATE ai_quota_buckets
SET reserved_tokens = reserved_tokens + #{tokens}, updated_at = #{now}
WHERE user_id = #{userId} AND quota_date = #{quotaDate}

UPDATE ai_quota_buckets
SET reserved_tokens = reserved_tokens - #{reservedTokens},
    consumed_tokens = consumed_tokens + #{actualTokens},
    updated_at = #{now}
WHERE user_id = #{userId} AND quota_date = #{quotaDate}

UPDATE ai_quota_buckets
SET consumed_tokens = consumed_tokens + #{actualTokens}, updated_at = #{now}
WHERE user_id = #{userId} AND quota_date = #{quotaDate}

UPDATE ai_quota_user_concurrency
SET active_reservations = active_reservations + 1, updated_at = #{now}
WHERE user_id = #{userId}

UPDATE ai_quota_user_concurrency
SET active_reservations = active_reservations - 1, updated_at = #{now}
WHERE user_id = #{userId}
